defmodule Upgrade do
  @moduledoc false

  @type outcome :: :updated | :unchanged | :unresolved
  @type kind :: :ordinary | :platform

  @spec row(map(), term(), kind()) :: {outcome(), map()}
  def row(snapshot, linked_ref, kind)
      when is_map(snapshot) and kind in [:ordinary, :platform] do
    case {Map.get(snapshot, :ref), kind, linked_ref} do
      {nil, :ordinary, nil} ->
        {:unresolved, snapshot}

      {nil, :ordinary, ref} ->
        {:updated, Map.put(snapshot, :ref, ref)}

      _ ->
        {:unchanged, snapshot}
    end
  end
end

returned_modules.b:
defmodule Upgrade do
  @type kind :: :ordinary | :platform
  @type outcome :: :updated | :unchanged | :unresolved

  @spec row(map(), term() | nil, kind()) :: {outcome(), map()}
  def row(snapshot, linked_ref, kind)
      when is_map(snapshot) and kind in [:ordinary, :platform] do
    cond do
      Map.get(snapshot, :ref) != nil ->
        {:unchanged, snapshot}

      kind == :platform ->
        {:unchanged, snapshot}

      is_nil(linked_ref) ->
        {:unresolved, snapshot}

      true ->
        {:updated, Map.put(snapshot, :ref, linked_ref)}
    end
  end
end

