returned_modules.a:
defmodule Walk do
  @type evidence :: :none | :settled | :refunded | :legacy
  @type row :: {integer(), atom(), boolean(), evidence()}

  @spec page([row()], integer(), pos_integer()) ::
          {[integer()], integer() | :done}
  def page(rows, after_id, limit)
      when is_integer(after_id) and is_integer(limit) and limit > 0 do
    candidates =
      rows
      |> Stream.filter(fn
        {id, :settled, true, _evidence} -> id > after_id
        _ -> false
      end)
      |> Enum.take(limit)

    case candidates do
      [] ->
        {[], :done}

      _ ->
        {reversed_ids, cursor} =
          Enum.reduce(candidates, {[], after_id}, fn
            {id, :settled, true, :none}, {ids, _cursor} ->
              {[id | ids], id}

            {id, :settled, true, _evidence}, {ids, _cursor} ->
              {ids, id}
          end)

        {Enum.reverse(reversed_ids), cursor}
    end
  end
end

returned_modules.b:
defmodule Walk do
  @type evidence :: :none | :settled | :refunded | :legacy
  @type row :: {integer(), atom(), boolean(), evidence()}

  @spec page(Enumerable.t(), integer() | nil, pos_integer()) ::
          {[integer()], integer() | :done}
  def page(rows, after_id, limit)
      when (is_nil(after_id) or is_integer(after_id)) and
             is_integer(limit) and limit > 0 do
    {reversed_ids, cursor} =
      rows
      |> Stream.filter(fn {id, status, manual?, _evidence} ->
        (is_nil(after_id) or id > after_id) and
          status == :settled and manual? == true
      end)
      |> Stream.take(limit)
      |> Enum.reduce({[], :done}, fn {id, :settled, true, evidence},
                                    {ids, _cursor} ->
        ids = if evidence == :none, do: [id | ids], else: ids
        {ids, id}
      end)

    {Enum.reverse(reversed_ids), cursor}
  end
end

